if __name__=='__main__':
 for id,methods in plan.items():
  file=dest/(id+'.trx'); log=dest/(id+'.log');start=time.time()
  cmd=['dotnet','test',str(project/'tests/SiLab.Tests/SiLab.Tests.csproj'),'-c','Release','--no-build','--filter','|'.join('FullyQualifiedName~'+m for m in methods),'--logger','trx;LogFileName='+file.name,'--results-directory',str(dest)]
  with log.open('w',encoding='utf-8') as out:p=subprocess.run(cmd,cwd=str(project),stdout=out,stderr=subprocess.STDOUT)
  actual=[]
  if file.exists():
   root=E.parse(file).getroot()
   actual=[{'test':r.get('testName'),'outcome':r.get('outcome'),'duration':r.get('duration')} for r in root.findall('.//{*}UnitTestResult')]
  result={'id':id,'method':'Integración .NET, base temporal independiente','started':start,'seconds':round(time.time()-start,2),'checks':actual,'passed':p.returncode==0 and bool(actual) and all(x['outcome']=='Passed' for x in actual),'evidence':str(file.relative_to(base)),'requestedMethods':methods}
  results.append(result);(base/'resultados-tecnicos.json').write_text(json.dumps(results,ensure_ascii=False,indent=2),encoding='utf-8')
  print(json.dumps({'id':id,'checks':len(actual),'passed':result['passed'],'seconds':result['seconds']},ensure_ascii=False),flush=True)
